-- Dev seed for payment_db (docker/dev profile only). Idempotent.
-- enrollment_cache mirrors active enrollments; a PAID Aug cycle + UNPAID Sep cycle for demo.

ON CONFLICT (ENROLLMENT_ID) DO NOTHING;

-- Fee cycles: student1 Aug 2026 (PAID, 5500) and Sep 2026 (UNPAID, 5500); student2 Sep 2026 (UNPAID, 2500).
ON CONFLICT (STUDENT_ID, BILLING_MONTH, BILLING_YEAR) DO NOTHING;

-- Fee details per cycle (one per enrollment).
ON CONFLICT (FEE_CYCLE_ID, ENROLLMENT_ID) DO NOTHING;

-- Payment settling student1's Aug cycle, with allocations to its two details.
ON CONFLICT (ID) DO NOTHING;

ON CONFLICT (ID) DO NOTHING;
